//! Back-to-back tests: code generated by `middleware_model!` against the
//! runtime `middleware::state_machine::StateMachine` as an independent oracle.
//!
//! For each model under test the YAML is read twice, by two independent
//! paths:
//!
//! - the macro expands it into a generated state machine module (the
//!   `TRANSITIONS` table, `on_enter`/`on_exit` and the pure `step` function);
//! - this test parses the same file with `serde_yaml` into a [`Spec`] and
//!   builds a runtime `StateMachine` table from it, mapping names to the
//!   generated enum variants by their `Debug` name only. No generated table,
//!   lookup or step logic is used to build the oracle.
//!
//! Three kinds of check are made per model:
//!
//! 1. `table_matches_yaml`: the generated enums, table rows, guards,
//!    actions, lifecycle hooks and initial state equal the YAML.
//! 2. `generated_matches_runtime` (proptest, [`CASES`] cases per model):
//!    random event sequences of length 0 to 63, with random guard outcomes
//!    and occasionally a failing action, drive both machines in lockstep.
//!    At every step the state reached, the outcome (transitioned with from
//!    and to, remained, ignored, or the failure kind) and the ordered list
//!    of actions invoked must be equal.
//! 3. `lockstep_covers_every_row`: a deterministic run of the same lockstep
//!    over [`COVERAGE_SEQUENCES`] seeded sequences must fire every table row
//!    and produce every outcome kind, so property 2 is not vacuous. The row
//!    that fired is identified independently from the YAML rows: the first
//!    row matching (state, event) whose guard is absent or true.
//!
//! The runtime `StateMachine` consumes itself and its context when an
//! action fails, so the oracle records invoked actions in a thread-local
//! log ([`RUNTIME_LOG`]) that survives the error, and each step rebuilds the
//! runtime machine from the previous state with `StateMachine::new`. That
//! matches the generated contract, where the caller keeps its previous
//! state on a hook error.
//!
//! A failing hook is injected by action index. The oracle reports it to the
//! runtime as [`LifecycleError::ExitActionFailed`] or
//! [`LifecycleError::EntryActionFailed`] from `on_exit`/`on_enter` and as
//! [`StateMachineError::ActionFailed`] from a transition action; the
//! runtime maps these to `FsmError::{ExitFailed, EntryFailed, ActionFailed}`.
//!
//! # Duplicate (state, event) rows
//! Both implementations scan rows in table order and fire the first row
//! matching (state, event) whose guard is absent or passes; if rows matched
//! but every guard failed the outcome is `Remained`. Models with several
//! rows per (state, event) are therefore inside the compared domain, and
//! `fixtures/b2b_duplicate_rows.yaml` is run through the same lockstep
//! property, plus `duplicate_rows::fallthrough_agrees`, a deterministic
//! lockstep check of the fall-through and all-guards-false cases.
//!
//! Models: `examples/attitude_controller.yaml` (guards, transition actions,
//! enter and exit hooks), `fixtures/b2b_door.yaml` (shared guards,
//! guarded and unguarded self-loops, an action used both on a transition and
//! on entry, and an enum variant with no state entry) and
//! `fixtures/b2b_duplicate_rows.yaml` (guarded rows followed by a fallback
//! row, two guarded rows on one pair, hooks for every failure kind).
//!
//! # Traceability
//! - REQ-GEN-011: generated state machine implementations
//! - REQ-FSM-002: on_enter and on_exit actions
//! - REQ-FSM-011: guard conditions
//! - REQ-FSM-012: transition actions
//! - REQ-FSM-013: compile-time transition tables
//! - REQ-FSM-021, REQ-FSM-022: event processing and transition results

// test code: a panic is a test failure, which is the intended reporting mechanism
#![cfg_attr(test, allow(clippy::expect_used, clippy::panic, clippy::indexing_slicing))]

use std::cell::RefCell;
use std::sync::OnceLock;

use middleware::state_machine::{
    ActionFn, Event, FsmError, GuardFn, State, StateMachine, Transition, TransitionResult,
};
use middleware::{LifecycleError, StateMachineError};
use proptest::prelude::*;
use proptest::strategy::ValueTree;
use serde_yaml::Value;

// Paths are relative to this file, like `include_str!`.
middleware_codegen::middleware_model!("../../examples/attitude_controller.yaml");
middleware_codegen::middleware_model!("fixtures/b2b_door.yaml");
middleware_codegen::middleware_model!("fixtures/b2b_duplicate_rows.yaml");

const ATTITUDE_YAML: &str = include_str!("../../examples/attitude_controller.yaml");
const DOOR_YAML: &str = include_str!("fixtures/b2b_door.yaml");
const DUP_YAML: &str = include_str!("fixtures/b2b_duplicate_rows.yaml");

/// Every outcome kind, for models whose hooks can produce all of them.
const ALL_KINDS: &[&str] =
    &["transitioned", "remained", "ignored", "exit_failed", "action_failed", "entry_failed"];

/// Proptest cases per model for the lockstep property.
const CASES: u32 = 1024;

/// Seeded sequences used by the coverage check.
const COVERAGE_SEQUENCES: usize = 512;

/// Upper bound on distinct guards and actions per model in this harness.
const MAX_HOOKS: usize = 12;

// ---------------------------------------------------------------------------
// Independent model reading
// ---------------------------------------------------------------------------

/// One transition row, with names replaced by indices into [`Spec`] lists.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Row {
    from: usize,
    event: usize,
    to: usize,
    guard: Option<usize>,
    action: Option<usize>,
}

/// A state machine as read directly from the YAML by this test.
#[derive(Debug)]
pub struct Spec {
    /// Variants of the state enum, in declaration order.
    states: Vec<String>,
    /// Variants of the event enum, in declaration order.
    events: Vec<String>,
    /// Distinct guard names.
    guards: Vec<String>,
    /// Distinct action names (transition, enter and exit).
    actions: Vec<String>,
    initial: usize,
    rows: Vec<Row>,
    /// Entry action per state variant.
    on_enter: Vec<Option<usize>>,
    /// Exit action per state variant.
    on_exit: Vec<Option<usize>>,
}

fn text(v: &Value) -> String {
    v.as_str().expect("string value").to_string()
}

fn position(list: &[String], name: &str) -> usize {
    list.iter().position(|n| n == name).unwrap_or_else(|| panic!("unknown name {name}"))
}

fn intern(list: &mut Vec<String>, name: &str) -> usize {
    match list.iter().position(|n| n == name) {
        Some(i) => i,
        None => {
            list.push(name.to_string());
            list.len() - 1
        }
    }
}

fn enum_variants(doc: &Value, name: &str) -> Vec<String> {
    doc["types"]["enums"]
        .as_sequence()
        .expect("enums")
        .iter()
        .find(|e| e["name"].as_str() == Some(name))
        .unwrap_or_else(|| panic!("enum {name}"))["variants"]
        .as_sequence()
        .expect("variants")
        .iter()
        .map(text)
        .collect()
}

impl Spec {
    fn from_yaml(yaml: &str, fsm_name: &str) -> Spec {
        let doc: Value = serde_yaml::from_str(yaml).expect("fixture YAML");
        let fsm = doc["state_machines"]
            .as_sequence()
            .expect("state_machines")
            .iter()
            .find(|f| f["name"].as_str() == Some(fsm_name))
            .expect("state machine")
            .clone();
        let states = enum_variants(&doc, fsm["state_type"].as_str().expect("state_type"));
        let events = enum_variants(&doc, fsm["events"].as_str().expect("events"));
        let mut guards = Vec::new();
        let mut actions = Vec::new();
        let mut on_enter = vec![None; states.len()];
        let mut on_exit = vec![None; states.len()];
        for s in fsm["states"].as_sequence().expect("states") {
            let i = position(&states, s["name"].as_str().expect("state name"));
            on_enter[i] = s["on_enter"].as_str().map(|a| intern(&mut actions, a));
            on_exit[i] = s["on_exit"].as_str().map(|a| intern(&mut actions, a));
        }
        let rows = fsm["transitions"]
            .as_sequence()
            .expect("transitions")
            .iter()
            .map(|t| Row {
                from: position(&states, t["from"].as_str().expect("from")),
                event: position(&events, t["event"].as_str().expect("event")),
                to: position(&states, t["to"].as_str().expect("to")),
                guard: t["guard"].as_str().map(|g| intern(&mut guards, g)),
                action: t["action"].as_str().map(|a| intern(&mut actions, a)),
            })
            .collect();
        let initial = position(&states, fsm["initial_state"].as_str().expect("initial"));
        assert!(guards.len() <= MAX_HOOKS && actions.len() <= MAX_HOOKS);
        Spec { states, events, guards, actions, initial, rows, on_enter, on_exit }
    }
}

/// snake_case to PascalCase, written independently of the generator.
fn pascal(name: &str) -> String {
    let mut out = String::new();
    let mut upper = true;
    for c in name.chars() {
        if c == '_' {
            upper = true;
        } else if upper {
            out.push(c.to_ascii_uppercase());
            upper = false;
        } else {
            out.push(c);
        }
    }
    out
}

fn debug_name<T: core::fmt::Debug>(value: T) -> String {
    format!("{value:?}")
}

// ---------------------------------------------------------------------------
// Runtime oracle context
// ---------------------------------------------------------------------------

thread_local! {
    /// Actions run by the runtime oracle during the current step. Kept
    /// outside the context because `StateMachine::process` drops the
    /// context when an action fails.
    static RUNTIME_LOG: RefCell<Vec<usize>> = const { RefCell::new(Vec::new()) };
}

/// Context of the runtime oracle for one step.
pub struct Ctx {
    spec: &'static Spec,
    guards: Vec<bool>,
    fail: Option<usize>,
}

/// Runs action `action` for the runtime oracle: fails if it is the injected
/// failing action, otherwise records it in [`RUNTIME_LOG`]. Callers map the
/// failure to the error type of the hook kind that ran it.
fn run_action(ctx: &Ctx, action: usize) -> Result<(), ()> {
    if ctx.fail == Some(action) {
        Err(())
    } else {
        RUNTIME_LOG.with(|log| log.borrow_mut().push(action));
        Ok(())
    }
}

fn guard_at<const I: usize>(ctx: &Ctx) -> bool {
    ctx.guards[I]
}

fn action_at<const I: usize>(ctx: &mut Ctx) -> Result<(), StateMachineError> {
    run_action(ctx, I).map_err(|()| StateMachineError::ActionFailed)
}

const GUARD_FNS: [GuardFn<Ctx>; MAX_HOOKS] = [
    guard_at::<0>,
    guard_at::<1>,
    guard_at::<2>,
    guard_at::<3>,
    guard_at::<4>,
    guard_at::<5>,
    guard_at::<6>,
    guard_at::<7>,
    guard_at::<8>,
    guard_at::<9>,
    guard_at::<10>,
    guard_at::<11>,
];

const ACTION_FNS: [ActionFn<Ctx>; MAX_HOOKS] = [
    action_at::<0>,
    action_at::<1>,
    action_at::<2>,
    action_at::<3>,
    action_at::<4>,
    action_at::<5>,
    action_at::<6>,
    action_at::<7>,
    action_at::<8>,
    action_at::<9>,
    action_at::<10>,
    action_at::<11>,
];

/// What one step did, in implementation-neutral terms.
#[derive(Debug, Clone, PartialEq, Eq)]
enum Obs {
    Transitioned { from: String, to: String },
    Remained,
    Ignored,
    ExitFailed,
    ActionFailed,
    EntryFailed,
}

/// One random step: event selector, guard outcome bits, optional failing
/// action selector. Selectors are reduced modulo the model's list sizes.
type StepInput = (usize, u16, Option<usize>);

fn steps_strategy() -> impl Strategy<Value = Vec<StepInput>> {
    prop::collection::vec(
        (0..64usize, any::<u16>(), prop::option::weighted(0.1, 0..64usize)),
        0..64,
    )
}

/// Per-sequence record used by the coverage check.
#[derive(Debug, Default)]
struct Coverage {
    rows_fired: Vec<usize>,
    kinds: Vec<&'static str>,
}

fn kind(obs: &Obs) -> &'static str {
    match obs {
        Obs::Transitioned { .. } => "transitioned",
        Obs::Remained => "remained",
        Obs::Ignored => "ignored",
        Obs::ExitFailed => "exit_failed",
        Obs::ActionFailed => "action_failed",
        Obs::EntryFailed => "entry_failed",
    }
}

// ---------------------------------------------------------------------------
// Per-model harness
// ---------------------------------------------------------------------------

macro_rules! back_to_back {
    (
        mod $m:ident,
        yaml: $yaml:expr,
        ns: $ns:ident,
        fsm: $fsm:ident,
        state: $S:ident,
        event: $E:ident,
        guards: [$($g:ident),* $(,)?],
        actions: [$($a:ident),* $(,)?],
        kinds: $kinds:expr
        $(, extra: { $($extra:item)* })? $(,)?
    ) => {
        mod $m {
            use super::*;
            use crate::$ns::$fsm as Fsm;
            use crate::$ns::{$E, $S};

            fn spec() -> &'static Spec {
                static SPEC: OnceLock<Spec> = OnceLock::new();
                SPEC.get_or_init(|| Spec::from_yaml($yaml, stringify!($fsm)))
            }

            fn state_value(name: &str) -> $S {
                *$S::ALL.iter().find(|s| debug_name(**s) == name).expect("state variant")
            }

            fn event_value(name: &str) -> $E {
                *$E::ALL.iter().find(|e| debug_name(**e) == name).expect("event variant")
            }

            fn state_index(state: $S) -> usize {
                position(&spec().states, &debug_name(state))
            }

            impl State for $S {
                type Context = Ctx;
                fn on_enter(&self, ctx: &mut Ctx) -> Result<(), LifecycleError> {
                    match ctx.spec.on_enter[state_index(*self)] {
                        Some(a) => run_action(ctx, a)
                            .map_err(|()| LifecycleError::EntryActionFailed),
                        None => Ok(()),
                    }
                }
                fn on_exit(&self, ctx: &mut Ctx) -> Result<(), LifecycleError> {
                    match ctx.spec.on_exit[state_index(*self)] {
                        Some(a) => run_action(ctx, a)
                            .map_err(|()| LifecycleError::ExitActionFailed),
                        None => Ok(()),
                    }
                }
            }

            impl Event for $E {
                const NAME: &'static str = stringify!($E);
            }

            /// Runtime table built from the YAML spec only.
            fn runtime_table() -> &'static [Transition<$S, $E>; Fsm::TRANSITION_COUNT] {
                static TABLE: OnceLock<[Transition<$S, $E>; Fsm::TRANSITION_COUNT]> =
                    OnceLock::new();
                TABLE.get_or_init(|| {
                    let s = spec();
                    let rows: Vec<Transition<$S, $E>> = s
                        .rows
                        .iter()
                        .map(|r| Transition {
                            source: state_value(&s.states[r.from]),
                            event: event_value(&s.events[r.event]),
                            target: state_value(&s.states[r.to]),
                            guard: r.guard.map(|g| GUARD_FNS[g]),
                            action: r.action.map(|a| ACTION_FNS[a]),
                        })
                        .collect();
                    match rows.try_into() {
                        Ok(table) => table,
                        Err(_) => panic!("YAML row count differs from TRANSITION_COUNT"),
                    }
                })
            }

            /// Generated-side hooks, answering from the same step inputs.
            struct Hooks {
                guards: Vec<bool>,
                fail: Option<usize>,
                log: Vec<usize>,
            }

            impl Fsm::Hooks for Hooks {
                type Error = usize;
                $(
                    fn $g(&self) -> bool {
                        self.guards[position(&spec().guards, stringify!($g))]
                    }
                )*
                $(
                    fn $a(&mut self) -> Result<(), usize> {
                        let i = position(&spec().actions, stringify!($a));
                        if self.fail == Some(i) {
                            Err(i)
                        } else {
                            self.log.push(i);
                            Ok(())
                        }
                    }
                )*
            }

            /// Runs both machines in lockstep, failing on the first mismatch.
            fn lockstep(steps: &[StepInput]) -> Result<Coverage, TestCaseError> {
                let s = spec();
                let table = runtime_table();
                let mut coverage = Coverage::default();
                let mut gen_state = Fsm::INITIAL_STATE;
                let mut rt_state = state_value(&s.states[s.initial]);
                prop_assert_eq!(gen_state, rt_state);

                for (i, &(event_sel, bits, fail_sel)) in steps.iter().enumerate() {
                    let event = $E::ALL[event_sel % $E::COUNT];
                    let guards: Vec<bool> =
                        (0..s.guards.len()).map(|k| (bits >> k) & 1 == 1).collect();
                    let fail = match (fail_sel, s.actions.len()) {
                        (Some(f), n) if n > 0 => Some(f % n),
                        _ => None,
                    };

                    let mut hooks = Hooks { guards: guards.clone(), fail, log: Vec::new() };
                    let (gen_next, gen_obs) = match Fsm::step(gen_state, event, &mut hooks) {
                        Ok((next, Fsm::Outcome::Transitioned { from, to })) => (
                            next,
                            Obs::Transitioned { from: debug_name(from), to: debug_name(to) },
                        ),
                        Ok((next, Fsm::Outcome::Remained)) => (next, Obs::Remained),
                        Ok((next, Fsm::Outcome::Ignored)) => (next, Obs::Ignored),
                        Err(Fsm::StepError::ExitFailed(_)) => (gen_state, Obs::ExitFailed),
                        Err(Fsm::StepError::ActionFailed(_)) => (gen_state, Obs::ActionFailed),
                        Err(Fsm::StepError::EntryFailed(_)) => (gen_state, Obs::EntryFailed),
                    };

                    RUNTIME_LOG.with(|log| log.borrow_mut().clear());
                    let machine = StateMachine::new(
                        rt_state,
                        Ctx { spec: s, guards: guards.clone(), fail },
                        table,
                    );
                    let (rt_next, rt_obs) = match machine.process(event) {
                        Ok((m, TransitionResult::Transitioned { from, to })) => (
                            m.current_state(),
                            Obs::Transitioned { from: debug_name(from), to: debug_name(to) },
                        ),
                        Ok((m, TransitionResult::Remained)) => (m.current_state(), Obs::Remained),
                        Ok((m, TransitionResult::Ignored)) => (m.current_state(), Obs::Ignored),
                        Err(FsmError::ExitFailed) => (rt_state, Obs::ExitFailed),
                        Err(FsmError::ActionFailed) => (rt_state, Obs::ActionFailed),
                        Err(FsmError::EntryFailed) => (rt_state, Obs::EntryFailed),
                    };
                    let rt_log = RUNTIME_LOG.with(|log| log.take());

                    prop_assert_eq!(&gen_obs, &rt_obs, "outcome at step {} ({:?})", i, event);
                    prop_assert_eq!(gen_next, rt_next, "state at step {}", i);
                    prop_assert_eq!(&hooks.log, &rt_log, "actions at step {}", i);

                    if matches!(gen_obs, Obs::Transitioned { .. }) {
                        let from = state_index(gen_state);
                        let ev = position(&s.events, &debug_name(event));
                        // First matching row whose guard is absent or true.
                        let row = s.rows.iter().position(|r| {
                            r.from == from && r.event == ev && r.guard.is_none_or(|g| guards[g])
                        });
                        coverage.rows_fired.extend(row);
                    }
                    coverage.kinds.push(kind(&gen_obs));
                    gen_state = gen_next;
                    rt_state = rt_next;
                }
                Ok(coverage)
            }

            #[test]
            fn table_matches_yaml() {
                let s = spec();
                let names: Vec<String> = $S::ALL.iter().map(|v| debug_name(*v)).collect();
                assert_eq!(names, s.states);
                let names: Vec<String> = $E::ALL.iter().map(|v| debug_name(*v)).collect();
                assert_eq!(names, s.events);
                for (i, v) in $S::ALL.iter().enumerate() {
                    assert_eq!(usize::from(v.to_repr()), i, "state discriminant");
                }
                assert_eq!(Fsm::INITIAL_STATE, state_value(&s.states[s.initial]));
                assert_eq!(Fsm::TRANSITION_COUNT, s.rows.len());
                for (generated, row) in Fsm::TRANSITIONS.iter().zip(&s.rows) {
                    assert_eq!(debug_name(generated.from), s.states[row.from]);
                    assert_eq!(debug_name(generated.event), s.events[row.event]);
                    assert_eq!(debug_name(generated.to), s.states[row.to]);
                    assert_eq!(
                        generated.guard.map(debug_name),
                        row.guard.map(|g| pascal(&s.guards[g]))
                    );
                    assert_eq!(
                        generated.action.map(debug_name),
                        row.action.map(|a| pascal(&s.actions[a]))
                    );
                }
                for (i, v) in $S::ALL.iter().enumerate() {
                    assert_eq!(
                        Fsm::on_enter(*v).map(debug_name),
                        s.on_enter[i].map(|a| pascal(&s.actions[a]))
                    );
                    assert_eq!(
                        Fsm::on_exit(*v).map(debug_name),
                        s.on_exit[i].map(|a| pascal(&s.actions[a]))
                    );
                }
            }

            proptest! {
                #![proptest_config(ProptestConfig::with_cases(CASES))]

                #[test]
                fn generated_matches_runtime(steps in steps_strategy()) {
                    lockstep(&steps)?;
                }
            }

            #[test]
            fn lockstep_covers_every_row() {
                let mut runner = proptest::test_runner::TestRunner::deterministic();
                let strategy = steps_strategy();
                let mut fired = vec![false; spec().rows.len()];
                let mut kinds: Vec<&'static str> = Vec::new();
                for _ in 0..COVERAGE_SEQUENCES {
                    let steps = strategy.new_tree(&mut runner).expect("strategy").current();
                    let coverage = lockstep(&steps).expect("lockstep agreement");
                    for r in coverage.rows_fired {
                        fired[r] = true;
                    }
                    kinds.extend(coverage.kinds);
                }
                assert!(fired.iter().all(|f| *f), "rows never fired: {fired:?}");
                let expected: &[&str] = $kinds;
                for k in expected {
                    assert!(kinds.contains(k), "outcome kind {k} never produced");
                }
            }

            $($($extra)*)?
        }
    };
}

back_to_back! {
    mod attitude,
    yaml: ATTITUDE_YAML,
    ns: attitude_control,
    fsm: ControllerStateMachine,
    state: SystemState,
    event: SystemEvent,
    guards: [sensors_calibrated, fault_resolved],
    actions: [
        initialize_sensors,
        prepare_control_loop,
        enable_control,
        disable_control,
        log_fault,
        cleanup_resources,
        arm_actuators,
        disarm_actuators,
    ],
    kinds: ALL_KINDS,
}

back_to_back! {
    mod door,
    yaml: DOOR_YAML,
    ns: b2b_door,
    fsm: DoorMachine,
    state: DoorState,
    event: DoorEvent,
    guards: [power_ok, path_clear, authorised],
    actions: [stop_motor, start_motor, log_state, engage_lock, release_lock, raise_alarm],
    kinds: ALL_KINDS,
}

back_to_back! {
    mod duplicate_rows,
    yaml: DUP_YAML,
    ns: b2b_dup,
    fsm: DupMachine,
    state: DupState,
    event: DupEvent,
    guards: [low_ok, high_ok],
    actions: [leave_low, arrive_high, take_low, take_high],
    kinds: ALL_KINDS,
    extra: {
        /// Guard bit for `name` in a [`StepInput`].
        fn guard_bit(name: &str) -> u16 {
            1 << position(&spec().guards, name)
        }

        /// Event selector for `event` in a [`StepInput`].
        fn event_sel(event: DupEvent) -> usize {
            position(&spec().events, &debug_name(event))
        }

        /// Deterministic lockstep over the duplicate-row cases: a failing
        /// first guard falls through to the next matching row, the first
        /// passing row wins, and all guards false gives `Remained`. Both
        /// implementations must agree at every step, and the expected row
        /// must fire.
        #[test]
        fn fallthrough_agrees() {
            let go = event_sel(DupEvent::Go);
            let low = guard_bit("low_ok");
            let high = guard_bit("high_ok");
            let row = |from: &str, to: &str| {
                let s = spec();
                s.rows
                    .iter()
                    .position(|r| s.states[r.from] == from && s.states[r.to] == to)
                    .expect("row")
            };

            // Idle --Go--> High: low_ok false, so the unguarded second row fires.
            let coverage = lockstep(&[(go, 0, None)]).expect("lockstep agreement");
            assert_eq!(coverage.kinds, ["transitioned"]);
            assert_eq!(coverage.rows_fired, [row("Idle", "High")]);

            // Idle --Go--> Low: the first row passes and wins over the fallback.
            let coverage = lockstep(&[(go, low | high, None)]).expect("lockstep agreement");
            assert_eq!(coverage.rows_fired, [row("Idle", "Low")]);

            // From Low: both guards false remains, then high_ok alone falls
            // through to the second (Low, Go) row.
            let coverage = lockstep(&[(go, low, None), (go, 0, None), (go, high, None)])
                .expect("lockstep agreement");
            assert_eq!(coverage.kinds, ["transitioned", "remained", "transitioned"]);
            assert_eq!(coverage.rows_fired, [row("Idle", "Low"), row("Low", "High")]);

            // The generated side agrees on the concrete states, independent
            // of the oracle.
            let mut hooks = Hooks { guards: vec![false, false], fail: None, log: Vec::new() };
            let (state, outcome) = Fsm::step(DupState::Idle, DupEvent::Go, &mut hooks)
                .expect("no failing hook");
            assert_eq!(state, DupState::High);
            assert_eq!(
                outcome,
                Fsm::Outcome::Transitioned { from: DupState::Idle, to: DupState::High }
            );
        }
    },
}
